Ext._define('rh.pension.PensionerGrid', {
    extend: 'core.RestfulGrid',

    rest: 'rh.pension.PensionerRestful',
    restWindow: 'rh.pension.PensionerWindow',


    configOrderToolBar: ['search', '->','-','vincular', 'download'],


    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Nome', dataIndex: 'nome', id: 'autoExpandColumn', sortable: true},
                    {header: 'Nascimento', dataIndex: 'data_nascimento', width: 85, renderer: Ext.util.Format.dateRenderer('d/m/Y'), sortable: true},
                    {header: 'CPF', dataIndex: 'cpf', width: 90, sortable: true},
                    {header: 'Estado civil', dataIndex: 'estado_civil_display', width: 190, sortable: true},
                    {header: 'Raça/Cor', dataIndex: 'raca_cor_display', width: 115, sortable: true},
                    {header: 'Sangue', dataIndex: 'sangue_display', width: 90, sortable: true},
                ]
            );

        return this._columnModel;
    },

    getConfigActionsItems: function(cfg){
        var menu = rh.pension.PensionerGrid.superclass.getConfigActionsItems.call(this, cfg);
        menu['vincular'] = {
                text: 'Víncular pensionista',
                iconCls: 'icon-esocial icon-refresh',
                scope: this,
                handler: this.vincularPensionista
        };
       
        return menu;
    },


    vincularPensionista: function(cfg){
        var selected = this.getSelectionModel().getSelected();

        if(selected) {
            Ext.Msg.show({
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Tem certeza que deseja víncular o pensionista ao lancaçamento?',
                scope: this,
                fn: function(b) {
                    if(b == 'no') return;
                    Ext.Ajax.request({
                        'url': toolkit.util.Normalize.controller_action('GFPPayCheck', 'vincular_pensionista'),
                        'disableCaching': false,
                        'params': {'pk': selected.get('pk'), 'evento_id': this.baseParams.evento_id},
                        'method': 'POST',
                        'success': function(request) {
                            var obj = Ext.decode(request.responseText);
                            if(obj.message) {
                                Ext.MessageBox.show({
                                   title: 'Erro',
                                   msg: obj.message,
                                   buttons: Ext.MessageBox.OK,
                                   icon: obj.success? Ext.MessageBox.INFO: Ext.MessageBox.ERROR
                                })
                            }
                            if(obj.success)
                                this.getStore().load({});
                        },
                        'failure': function(request) {
                            Ext.MessageBox.show({
                               title: 'Erro',
                               msg: 'Ocorreu um erro inesperado',
                               buttons: Ext.MessageBox.OK,
                               icon: Ext.MessageBox.ERROR
                            });
                        },
                        'scope': this
                    });
                }
            });
        }
        else Ext.Msg.show({
            'title': 'Víncular pensionista',
            'msg': 'Selecione um lançamento de pensão!',
            'buttons': Ext.Msg.OK,
            'icon': Ext.Msg.WARN
        });
    },
});




core.RestfulGrid.register(
    'rh.pension.PensionerRestful',
    'rh.pension.PensionerGrid'
);
